.biometric-wrap {
  display: flex; flex-direction: column; align-items: center; gap: 20px;
}
.fingerprint-path {
  fill: none;
  stroke: #00d2ff;
  stroke-width: 4;
  stroke-linecap: round;
  stroke-dasharray: 400;
  stroke-dashoffset: 400;
  transition: stroke-dashoffset 2s ease-in-out, stroke 0.5s, filter 0.5s;
}
.biometric-wrap.scanned .fingerprint-path {
  stroke-dashoffset: 0;
  stroke: #00ffcc;
  filter: drop-shadow(0 0 10px #00ffcc);
}
.scan-text {
  color: #555; font-family: monospace; font-size: 16px; font-weight: bold; transition: color 0.5s;
}
.biometric-wrap.scanned .scan-text { color: #00ffcc; text-shadow: 0 0 10px #00ffcc; }

