const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'biometric-wrap';

const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
svg.setAttribute("width", "100");
svg.setAttribute("height", "100");
svg.setAttribute("viewBox", "0 0 100 100");

const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
// ERROR FIXED HERE:
path.setAttribute('class', 'fingerprint-path');
path.setAttribute("d", "M 20 50 C 20 20, 80 20, 80 50 C 80 80, 50 80, 50 50 C 50 30, 30 30, 30 60");

const text = document.createElement('div');
text.className = 'scan-text';
text.innerText = 'TAP TO SCAN';

svg.appendChild(path);
wrap.appendChild(svg);
wrap.appendChild(text);
c.appendChild(wrap);

wrap.addEventListener('click', () => {
  wrap.classList.add('scanned');
  text.innerText = 'ACCESS GRANTED';
  setTimeout(() => {
    wrap.classList.remove('scanned');
    text.innerText = 'TAP TO SCAN';
  }, 4000);
});
